package io.github.ilyaslabs.foodstack.platform.core;

import java.util.UUID;

import com.github.f4b6a3.uuid.UuidCreator;

/**
 * Identifiers generated by the application: time-ordered UUIDv7 strings.
 * <p>
 * Time ordering keeps index inserts local; collections keyed by these ids use a hashed shard key
 * so that new documents do not all land on one shard.
 */
public final class Ids {

    private Ids() {
    }

    /** A new UUIDv7 as a lower-case string. */
    public static String newId() {
        return UuidCreator.getTimeOrderedEpoch().toString();
    }

    /** Whether a value is a well-formed UUID string. */
    public static boolean isValid(String value) {
        if (value == null || value.length() != 36) {
            return false;
        }
        try {
            UUID.fromString(value);
            return true;
        }
        catch (IllegalArgumentException ex) {
            return false;
        }
    }
}
